{# ---------------- STOCK ENTRY MERGE LOGIC ---------------- #}

{%- set actual_transfers = {} -%}

{%- set se_list = frappe.db.get_list(
    "Stock Entry",
    {"stock_entry_type": "Send to Subcontractor", "subcontracting_order": doc.name},
    ["name"]
) or [] -%}

{%- for se_row in se_list -%}
    {%- set se = frappe.get_doc("Stock Entry", se_row.name) -%}
    {%- if se and se.items -%}
        {%- for entry in se.items -%}
            {%- if entry.item_code and entry.qty > 0 -%}
                {%- set code = entry.item_code -%}
                {%- if code in actual_transfers -%}
                    {%- set new_qty = actual_transfers[code].qty + entry.qty -%}
                    {%- set _ = actual_transfers[code].update({"qty": new_qty}) -%}
                {%- else -%}
                    {%- set item_master = frappe.db.get_value("Item", code, ["item_name","stock_uom"], as_dict=1) or {} -%}
                    {%- set _ = actual_transfers.update({
                        code: {
                            "item_code": code,
                            "item_name": item_master.item_name or code,
                            "uom": entry.stock_uom or item_master.stock_uom or "Nos",
                            "qty": entry.qty
                        }
                    }) -%}
                {%- endif -%}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}
{%- endfor -%}

{%- if actual_transfers and actual_transfers.values() -%}
    {%- set final_items = actual_transfers.values() | list -%}
{%- else -%}
    {%- set fallback = {} -%}
    {%- if doc.supplied_items -%}
        {%- for item in doc.supplied_items -%}
            {%- set code = item.rm_item_code -%}
            {%- if code -%}
                {%- if code in fallback -%}
                    {%- set new_qty = fallback[code].qty + item.required_qty -%}
                    {%- set _ = fallback[code].update({"qty": new_qty}) -%}
                {%- else -%}
                    {%- set item_master = frappe.db.get_value("Item", code, ["item_name","stock_uom"], as_dict=1) or {} -%}
                    {%- set _ = fallback.update({
                        code: {
                            "item_code": code,
                            "item_name": item_master.item_name or code,
                            "uom": item_master.stock_uom or "Nos",
                            "qty": item.required_qty
                        }
                    }) -%}
                {%- endif -%}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}
    {%- set final_items = fallback.values() | list -%}
{%- endif -%}

{# -------- MERGE RECEIVABLE -------- #}

{%- set merged_fg = {} -%}
{%- if doc.items -%}
    {%- for item in doc.items -%}
        {%- set code = item.item_code -%}
        {%- if code -%}
            {%- if code in merged_fg -%}
                {%- set new_qty = merged_fg[code].qty + item.qty -%}
                {%- set _ = merged_fg[code].update({"qty": new_qty}) -%}
            {%- else -%}
                {%- set _ = merged_fg.update({
                    code: {
                        "item_code": code,
                        "item_name": item.item_name or code,
                        "qty": item.qty
                    }
                }) -%}
            {%- endif -%}
        {%- endif -%}
    {%- endfor -%}
{%- endif -%}
{%- set final_fg = merged_fg.values() | list -%}

